fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    debug_assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    debug_assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    debug_assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Prepare the output vector
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        debug_assert!(
            c1 || c2,
            "At least one of conds_1[{}] or conds_2[{}] must be true",
            i,
            i
        );

        let value = if c1 && c2 {
            // Both true: integer average
            (vals_1[i] + vals_2[i]) / 2
        } else if c1 {
            // Only first is true
            vals_1[i]
        } else {
            // Only second is true
            vals_2[i]
        };

        avgs.push(value);
    }
}